// Prepare job v4 (2026-11-25): invalid recovery rows skipped; v3 (2026-11-19): tenant validation, deterministic keys, recovery rows from DB
const out = [];
for (const [idx, item] of $input.all().entries()) {
  const t = item.json;
  try {
  const tenant = typeof t.tenant_id === 'string' ? t.tenant_id.trim() : '';
  if (!/^tenant_[a-z0-9_]{1,56}$/.test(tenant)) throw new Error('Rejected: missing or invalid tenant_id');
  let scenario, jobKey, source, period, version;
  if (t.recovery === true) {
    // Recovery rows come from the database: tenant_id and job_key are read, never invented
    if (typeof t.job_key !== 'string' || !t.job_key.startsWith(tenant + ':')) throw new Error('Rejected: recovery job_key does not belong to tenant');
    jobKey = t.job_key;
    scenario = (t.payload && t.payload.scenario) || 'ok';
    source = 'recovery'; period = 'recovery'; version = 'recovery';
  } else {
    scenario = t.scenario || 'ok';
    source = t.source_id ? String(t.source_id).trim() : '';
    if (!/^[A-Za-z0-9._-]{1,80}$/.test(source)) throw new Error('Rejected: missing or invalid source_id');
    period = t.period ? String(t.period).trim() : 'once';
    if (!/^[A-Za-z0-9._-]{1,40}$/.test(period)) throw new Error('Rejected: invalid period');
    version = t.input_version ? String(t.input_version).trim() : 'v1';
    if (!/^[A-Za-z0-9._-]{1,20}$/.test(version)) throw new Error('Rejected: invalid input_version');
    jobKey = [tenant, 'recovery', source, period, version, scenario].join(':');
  }
  if (!['ok', 'http500', 'timeout', 'recover'].includes(scenario)) throw new Error('Rejected: invalid scenario');
  const worker = t.worker_id || ('n8n-exec-' + $execution.id);
  const ok = 'https://jsonplaceholder.typicode.com/posts/1';
  const fail500 = 'https://httpbin.org/status/500';
  const slow = 'https://httpbin.org/delay/6';
  let urls;
  if (scenario === 'http500') urls = [fail500, fail500, fail500];
  else if (scenario === 'timeout') urls = [slow, slow, slow];
  else if (scenario === 'recover') urls = [fail500, fail500, ok];
  else urls = [ok, ok, ok];
  out.push({ json: { tenant_id: tenant, scenario, worker_id: worker, job_key: jobKey, source_id: source, period, input_version: version, url1: urls[0], url2: urls[1], url3: urls[2] }, pairedItem: { item: idx } });
  } catch (e) {
    if (t.recovery === true) { console.log('skip recovery row: ' + e.message); continue; }
    throw e;
  }
}
return out;
